{"code": "from PIL import Image
import glob

data_dir = 'data_small/CovidDataset_70_30'
problematic_files = []

for split in ['Train', 'Test', 'Validation']:
    split_path = os.path.join(data_dir, split)
    for cls in os.listdir(split_path):
        cls_path = os.path.join(split_path, cls)
        files = glob.glob(os.path.join(cls_path, '*'))
        for f in files:
            try:
                with Image.open(f) as img:
                    img.verify()  # Verify it's a valid image
                    # Reopen to check if it can be loaded
                    with Image.open(f) as img:
                        img.load()
            except Exception as e:
                problematic_files.append((f, str(e)))
                print(f"Problematic file: {f} - Error: {e}")

print(f"\nTotal problematic files: {len(problematic_files)}")"}

